import{_ as e,o as t,f as r,a6 as o}from"./chunks/framework.BFhbG0o2.js";const d=JSON.parse('{"title":"AI 商业视觉生产系统","description":"从需求输入到资产沉淀的五阶段 AI 商业视觉工作流。","frontmatter":{"title":"AI 商业视觉生产系统","description":"从需求输入到资产沉淀的五阶段 AI 商业视觉工作流。","pageClass":"page-workflow-detail","status":"published"},"headers":[],"relativePath":"aigc/commercial-visual-system.md","filePath":"aigc/commercial-visual-system.md"}'),i={name:"aigc/commercial-visual-system.md"};function l(s,a,n,h,p,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="ai-商业视觉生产系统" tabindex="-1">AI 商业视觉生产系统 <a class="header-anchor" href="#ai-商业视觉生产系统" aria-label="Permalink to &quot;AI 商业视觉生产系统&quot;">​</a></h1><p>这套流程解决的不是“如何得到一张好图”，而是如何让 AI 进入真实商业项目：目标明确、变量可控、结果可筛选、交付可复盘。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>产品图、详情页视觉、品牌内容、展会提案、短视频画面探索，以及需要连续生产同类素材的任务。</p><h2 id="_01-需求输入" tabindex="-1">01 需求输入 <a class="header-anchor" href="#_01-需求输入" aria-label="Permalink to &quot;01 需求输入&quot;">​</a></h2><p>先定义业务目标、目标受众、使用场景、交付尺寸、时间、品牌限制和不可改变的产品事实。输入不清楚时，生成数量只会放大混乱。</p><p><strong>输出：</strong> 一页可执行简报，以及明确的验收标准。</p><h2 id="_02-变量拆解" tabindex="-1">02 变量拆解 <a class="header-anchor" href="#_02-变量拆解" aria-label="Permalink to &quot;02 变量拆解&quot;">​</a></h2><p>把画面拆为主体、场景、构图、镜头、光线、材质、色彩、文案位置和限制条件。固定不能改变的部分，只开放真正需要探索的变量。</p><p><strong>人工判断点：</strong> 哪些变量影响商业目标，哪些只是表面风格变化。</p><h2 id="_03-方向生成" tabindex="-1">03 方向生成 <a class="header-anchor" href="#_03-方向生成" aria-label="Permalink to &quot;03 方向生成&quot;">​</a></h2><p>先用少量方向测试建立边界，再批量扩展有效方向。每轮只改变有限变量，并保存生成条件，避免结果无法复现。</p><p><strong>输出：</strong> 可比较的方向池，而不是无序图片文件夹。</p><h2 id="_04-人工筛选与精修" tabindex="-1">04 人工筛选与精修 <a class="header-anchor" href="#_04-人工筛选与精修" aria-label="Permalink to &quot;04 人工筛选与精修&quot;">​</a></h2><p>按照产品真实性、信息清晰度、品牌一致性、审美质量、转化目标和执行成本筛选。AI 结果必须经过结构、文字、边缘、光影和品牌细节检查。</p><p><strong>边界：</strong> 涉及产品结构、医疗信息、承诺性文案和版权风险时，不以生成结果作为事实来源。</p><h2 id="_05-交付与资产沉淀" tabindex="-1">05 交付与资产沉淀 <a class="header-anchor" href="#_05-交付与资产沉淀" aria-label="Permalink to &quot;05 交付与资产沉淀&quot;">​</a></h2><p>统一文件命名、尺寸、版本和交付说明。项目结束后保留有效 Prompt 结构、参考图、参数、筛选原因、精修动作和复盘结论。</p><p><strong>输出：</strong> 本次交付物，以及下一次项目可以直接使用的资产包。</p><h2 id="关联实践与资源" tabindex="-1">关联实践与资源 <a class="header-anchor" href="#关联实践与资源" aria-label="Permalink to &quot;关联实践与资源&quot;">​</a></h2><ul><li><a href="/portfolio/ecommerce-visual.html">专业医疗产品电商视觉系统</a></li><li><a href="/portfolio/exhibition-visual.html">德国水处理展会视觉体系</a></li><li><a href="/resources/mj-prompt.html">商业视觉 Prompt 结构</a></li><li><a href="/resources/notion.html">AI 项目复盘清单</a></li></ul><p><a href="/aigc/">← 返回工作流</a></p>',22)])])}const u=e(i,[["render",l]]);export{d as __pageData,u as default};
